public static function muted( $html, $size = 12 ) {
		return '<tr><td style="font-size:' . (int) $size . 'px;line-height:1.6;color:' . self::C_MUTED . ';padding-bottom:14px;">' . $html . '</td></tr>';
	}

	/**
	 * VIENAS pagrindinis CTA (TZ §4.4.3: vienas mygtukas laiske).
	 */
	public static function button( $url, $label ) {
		if ( ! $url || ! $label ) { return ''; }
		return '<tr><td style="padding:6px 0 22px;">'
			. '<a href="' . esc_url( $url ) . '" '
			. 'style="background:' . self::C_ACCENT . ';color:#FFFFFF;text-decoration:none;'
			. 'padding:14px 26px;border-radius:8px;font-weight:600;font-size:15px;display:inline-block;">'
			. esc_html( $label ) . '</a></td></tr>';
	}

	/** Antriniai veiksmai — TIK tekstinės nuorodos. */
	public static function secondary( $links ) {
		$parts = array();
		foreach ( (array) $links as $label => $url ) {
			if ( ! $url ) { continue; }
			$parts[] = '<a href="' . esc_url( $url ) . '" style="color:' . self::C_ACCENT . ';">' . esc_html( $label ) . '</a>';
		}
		if ( ! $parts ) { return ''; }
		return '<tr><td style="font-size:14px;line-height:1.6;padding-bottom:20px;">' . implode( ' · ', $parts ) . '</td></tr>';
	}

	public static function divider() {
		return '<tr><td style="border-top:1px solid ' . self::C_LINE . ';font-size:0;line-height:0;height:1px;">&nbsp;</td></tr>';
	}

	/**
	 * Footeris. $flow_class: transactional | service | marketing.
	 * $reason — trumpas paaiskinimas „kodel gavote si laiska".
	 */
	public static function close( $flow_class = 'service', $email = '', $reason = '' ) {
		$out  = self::divider();
		$out .= '<tr><td style="font-size:12px;line-height:1.6;color:' . self::C_MUTED . ';padding-top:16px;">';
		$out .= 'UAB Avesa, Liucionių g. 46, Liucionys, LT-15166<br>';

		if ( $reason ) {
			$out .= esc_html( $reason ) . '<br>';
		}

		if ( 'marketing' === $flow_class ) {
			// Teisinis reikalavimas: veikianti atsisakymo nuoroda kiekviename laiske.
			$u = class_exists( 'Petshop_Unsubscribe' ) ? Petshop_Unsubscribe::link( $email ) : '';
			if ( $u ) {
				$out .= '<a href="' . esc_url( $u ) . '" style="color:' . self::C_MUTED . ';">Atsisakyti pranešimų</a>';
			}
		} elseif ( 'service' === $flow_class ) {
			// S320: „Pranesimu nustatymai" NERODOM kaip nuorodos — tokio puslapio
			// DAR NERA. Negyvas footerio linkas nera geresnis uz negyva CTA.
			// Kai atsiras realus destination — pakeisti i <a href>.
			$out .= 'Šis laiškas susijęs su jūsų užsakymu ar paskyra.';
		}

		$out .= '</td></tr>';
		$out .= '</table></td></tr></table></body></html>';
		return $out;
	}

